-- +goose Up
-- 1. Create the Polling Units Table
CREATE TABLE IF NOT EXISTS polling_units (
    id SERIAL PRIMARY KEY,
    name VARCHAR(500) NOT NULL,
    code VARCHAR(20),
    pu_code VARCHAR(100),
    registration_area_id INTEGER,
    state_id INTEGER NOT NULL REFERENCES c_states(id) ON DELETE CASCADE,
    state_name VARCHAR(255) NOT NULL,
    senatorial_district_id INTEGER REFERENCES senatorial_districts(id) ON DELETE CASCADE,
    senatorial_district_name VARCHAR(255),
    federal_constituency_id INTEGER REFERENCES federal_constituencies(id) ON DELETE CASCADE,
    federal_constituency_name VARCHAR(255),
    state_constituency_id INTEGER REFERENCES state_constituencies(id) ON DELETE CASCADE,
    state_constituency_name VARCHAR(255),
    lga_id INTEGER NOT NULL REFERENCES lgas(id) ON DELETE CASCADE,
    lga_name VARCHAR(255) NOT NULL,
    ward_id INTEGER NOT NULL REFERENCES wards(id) ON DELETE CASCADE,
    ward_name VARCHAR(255) NOT NULL,
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    precise_location TEXT,
    formatted_address TEXT,
    google_place_id VARCHAR(255),
    status VARCHAR(50) DEFAULT 'active'
);


CREATE INDEX idx_polling_units_pu_code ON polling_units (pu_code);
CREATE INDEX idx_polling_units_state_id ON polling_units (state_id);
CREATE INDEX idx_polling_units_senatorial_district_id ON polling_units (senatorial_district_id);
CREATE INDEX idx_polling_units_federal_constituency_id ON polling_units (federal_constituency_id);
CREATE INDEX idx_polling_units_state_constituency_id ON polling_units (state_constituency_id);
CREATE INDEX idx_polling_units_lga_id ON polling_units (lga_id);
CREATE INDEX idx_polling_units_ward_id ON polling_units (ward_id);

-- Trigram GIN indexes for fast ILIKE substring searches on name and pu_code
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX idx_polling_units_name_trgm ON polling_units USING gin (name gin_trgm_ops);
CREATE INDEX idx_polling_units_pu_code_trgm ON polling_units USING gin (pu_code gin_trgm_ops);

